1	`timescale 1ns / 1ns
2	//////////////////////////////////////////////////////////////////////////////////
3	//////////////////////////////////////////////////////////////////////////////////
4	// Author:Niculescu Vlad
5	// Module Name:    Fourier 
6	//////////////////////////////////////////////////////////////////////////////////
7	//////////////////////////////////////////////////////////////////////////////////
8	module Fourier(clk, start, xn_re, xn_im, fwd_inv, fwd_inv_we, scale_sch, scale_sch_we, rfd, xn_index, busy, edone, done, dv, xk_index, 
9					   xk_re, xk_im
10	    );
11	
12	input clk;
13	input start;
14	input [9:0] xn_re;
15	input [9:0] xn_im;
16	input fwd_inv;
17	input fwd_inv_we;
18	input [11:0] scale_sch;
19	input scale_sch_we;
20	output rfd;
21	output [10 : 0] xn_index;
22	output busy;
23	output edone;
24	output done;
25	output dv;
26	output [10 : 0] xk_index;
27	output [9 : 0] xk_re;
28	output [9 : 0] xk_im;
29	
30	
31	
32	fft your_instance_name (
33	  .clk(clk), // input clk
34	  .start(start), // input start
35	  .xn_re(xn_re), // input [9 : 0] xn_re
36	  .xn_im(xn_im), // input [9 : 0] xn_im
37	  .fwd_inv(fwd_inv), // input fwd_inv
38	  .fwd_inv_we(fwd_inv_we), // input fwd_inv_we
39	  .scale_sch(scale_sch), // input [11 : 0] scale_sch
40	  .scale_sch_we(scale_sch_we), // input scale_sch_we
41	  .rfd(rfd), // output rfd
42	  .xn_index(xn_index), // output [10 : 0] xn_index
